const contentData = $node['Load Content Draft'].json[0];
const socialPosts = JSON.parse($node['Generate Social Media Posts'].json.choices[0].message.content);
const emailNewsletter = JSON.parse($node['Create Email Newsletter'].json.choices[0].message.content);
const metadata = JSON.parse(contentData.metadata);
const seoElements = JSON.parse(contentData.seo_elements);

// Prepare comprehensive publishing package
const publishingPackage = {
  content_info: {
    content_id: contentData.content_id,
    title: contentData.title,
    slug: seoElements.slug,
    meta_title: seoElements.meta_title,
    meta_description: seoElements.meta_description,
    word_count: contentData.word_count,
    status: 'ready_for_publishing'
  },

  blog_content: {
    html_content: contentData.content_html,
    markdown_content: contentData.content_markdown,
    featured_image_url: '', // Will be populated by thumbnail generation
    categories: metadata.content_pillar ? [metadata.content_pillar] : ['General'],
    tags: seoElements.primary_keywords.concat(seoElements.secondary_keywords),
    author: 'AI Content Team',
    publication_date: new Date().toISOString(),
    reading_time: Math.ceil(contentData.word_count / 200) + ' min read'
  },

  seo_optimization: {
    primary_keyword: seoElements.primary_keywords[0],
    secondary_keywords: seoElements.secondary_keywords,
    internal_links: [], // To be populated
    external_links: [], // To be populated
    schema_markup: {
      '@context': 'https://schema.org',
      '@type': 'Article',
      'headline': contentData.title,
      'description': seoElements.meta_description,
      'wordCount': contentData.word_count,
      'datePublished': new Date().toISOString(),
      'author': {
        '@type': 'Organization',
        'name': 'AI Content Team'
      }
    }
  },

  social_media: {
    linkedin: socialPosts.linkedin || {},
    twitter: socialPosts.twitter || {},
    facebook: socialPosts.facebook || {},
    instagram: socialPosts.instagram || {},
    youtube: socialPosts.youtube || {}
  },

  email_campaign: {
    subject_lines: emailNewsletter.subject_lines || [],
    preheader: emailNewsletter.preheader || '',
    html_content: emailNewsletter.html_version || '',
    plain_text: emailNewsletter.plain_text || '',
    segments: emailNewsletter.segmentation || []
  },

  distribution_schedule: {
    blog_publish: new Date(Date.now() + 1 * 60 * 60 * 1000).toISOString(), // 1 hour from now
    social_linkedin: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(), // 2 hours
    social_twitter: new Date(Date.now() + 2.5 * 60 * 60 * 1000).toISOString(), // 2.5 hours
    social_facebook: new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString(), // 3 hours
    social_instagram: new Date(Date.now() + 4 * 60 * 60 * 1000).toISOString(), // 4 hours
    email_send: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() // 24 hours
  },

  analytics_setup: {
    utm_parameters: {
      utm_source: 'blog',
      utm_medium: 'content',
      utm_campaign: seoElements.slug,
      utm_content: 'organic'
    },
    conversion_tracking: {
      primary_goal: 'engagement',
      secondary_goal: 'newsletter_signup',
      success_metrics: ['time_on_page', 'scroll_depth', 'social_shares', 'email_clicks']
    }
  }
};

return publishingPackage;

const performanceData = $input.first().json;

// Aggregate performance metrics from multiple sources
const metrics = {
  content_id: performanceData.content_id,

  blog_metrics: {
    page_views: performanceData.google_analytics?.page_views || 0,
    unique_visitors: performanceData.google_analytics?.unique_visitors || 0,
    bounce_rate: performanceData.google_analytics?.bounce_rate || 0,
    avg_time_on_page: performanceData.google_analytics?.avg_time_on_page || 0,
    scroll_depth: performanceData.google_analytics?.scroll_depth || 0
  },

  social_metrics: {
    linkedin_engagement: {
      likes: performanceData.linkedin?.likes || 0,
      comments: performanceData.linkedin?.comments || 0,
      shares: performanceData.linkedin?.shares || 0,
      clicks: performanceData.linkedin?.clicks || 0
    },
    twitter_engagement: {
      likes: performanceData.twitter?.likes || 0,
      retweets: performanceData.twitter?.retweets || 0,
      replies: performanceData.twitter?.replies || 0,
      clicks: performanceData.twitter?.clicks || 0
    },
    total_social_engagement: 0 // Calculate total
  },

  email_metrics: {
    open_rate: performanceData.mailchimp?.open_rate || 0,
    click_rate: performanceData.mailchimp?.click_rate || 0,
    unsubscribe_rate: performanceData.mailchimp?.unsubscribe_rate || 0,
    forwards: performanceData.mailchimp?.forwards || 0
  },

  seo_metrics: {
    search_impressions: performanceData.search_console?.impressions || 0,
    search_clicks: performanceData.search_console?.clicks || 0,
    avg_position: performanceData.search_console?.avg_position || 0,
    ctr: performanceData.search_console?.ctr || 0
  },

  conversion_metrics: {
    leads_generated: performanceData.conversions?.leads || 0,
    email_signups: performanceData.conversions?.email_signups || 0,
    contact_form_submissions: performanceData.conversions?.contact_forms || 0,
    demo_requests: performanceData.conversions?.demo_requests || 0
  }
};

// Calculate total social engagement
metrics.social_metrics.total_social_engagement = 
  Object.values(metrics.social_metrics.linkedin_engagement).reduce((a, b) => a + b, 0) +
  Object.values(metrics.social_metrics.twitter_engagement).reduce((a, b) => a + b, 0);

// Calculate performance score (1-100)
const performanceScore = Math.min(100, Math.max(0, 
  (metrics.blog_metrics.page_views * 0.3) +
  (metrics.social_metrics.total_social_engagement * 0.4) +
  (metrics.email_metrics.open_rate * 100 * 0.2) +
  (metrics.conversion_metrics.leads_generated * 10 * 0.1)
));

metrics.overall_performance = {
  score: Math.round(performanceScore),
  grade: performanceScore >= 80 ? 'A' : performanceScore >= 60 ? 'B' : performanceScore >= 40 ? 'C' : 'D',
  status: performanceScore >= 70 ? 'high_performing' : performanceScore >= 40 ? 'moderate' : 'needs_improvement'
};

return {
  ...metrics,
  analysis_date: new Date().toISOString(),
  recommendations: {
    optimization_areas: [],
    content_improvements: [],
    distribution_adjustments: []
  }
};

const request = $input.first().json;

// Process multiple content pieces for bulk distribution
const contentList = request.content_list || [];
const distributionConfig = {
  batch_id: `dist_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  total_content: contentList.length,
  distribution_channels: request.channels || ['blog', 'social', 'email'],
  schedule_spread: request.schedule_spread || 'daily', // daily, weekly, optimal
  auto_optimize: request.auto_optimize || true,
  priority: request.priority || 'normal'
};

// Create distribution schedule
const now = new Date();
const distributionQueue = contentList.map((content, index) => {
  let scheduleOffset;

  switch (distributionConfig.schedule_spread) {
    case 'daily':
      scheduleOffset = index * 24 * 60 * 60 * 1000; // 1 day apart
      break;
    case 'weekly':
      scheduleOffset = index * 7 * 24 * 60 * 60 * 1000; // 1 week apart
      break;
    case 'optimal':
    default:
      // Spread based on optimal posting times
      scheduleOffset = index * 8 * 60 * 60 * 1000; // 8 hours apart
      break;
  }

  return {
    content_id: content.content_id || content.id,
    title: content.title,
    priority: content.priority || distributionConfig.priority,
    scheduled_time: new Date(now.getTime() + scheduleOffset).toISOString(),
    channels: content.channels || distributionConfig.distribution_channels,
    auto_optimize: distributionConfig.auto_optimize
  };
});

return {
  ...distributionConfig,
  distribution_queue: distributionQueue,
  estimated_completion: new Date(now.getTime() + (contentList.length * 8 * 60 * 60 * 1000)).toISOString()
};
